 private void lockView(View view,boolean locked){view.setAlpha(locked?0.42f:1f);setEnabledRecursive(view,!locked);}
 private void setEnabledRecursive(View view,boolean enabled){view.setEnabled(enabled);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)setEnabledRecursive(group.getChildAt(i),enabled);}}
 private int bodyTop(View view){int[] child=new int[2],base=new int[2];view.getLocationOnScreen(child);body.getLocationOnScreen(base);return child[1]-base[1];}
 private void updateStepScrollBounds(){if(scroll==null||body==null||resultScreen||setupStepView==null||secondStepStartView==null||inputsStepView==null){if(scroll!=null)scroll.setScrollBounds(0,Integer.MAX_VALUE);return;}int top,bottom;if(editorStep==1){top=0;bottom=Math.max(0,bodyTop(setupStepView)+setupStepView.getHeight()-scroll.getHeight()+dp(20));}else{int inputTop=bodyTop(inputsStepView),unitTop=bodyTop(secondStepStartView);top=Math.max(0,Math.min(inputTop,unitTop)-dp(12));bottom=Math.max(top,Math.max(inputTop+inputsStepView.getHeight(),unitTop+secondStepStartView.getHeight())-scroll.getHeight()+dp(20));}scroll.setScrollBounds(top,bottom);}
 private void rerenderPreservingScroll(){pendingScrollY=scroll==null?0:scroll.getScrollY();render();}
