 private void watch(EditText e,java.util.function.Consumer<String> c){e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(!building)c.accept(s.toString());}public void afterTextChanged(Editable s){}});}
 private BigDecimal number(String s){try{return new BigDecimal(s.trim().replace(',','.'));}catch(Exception e){throw new IllegalArgumentException("NUMBER");}}
 private boolean remainderMode(){return percent&&(type!=3||number(custom[1]).compareTo(new BigDecimal("3"))==0);}
 private boolean dropdownMode(){return percent&&type!=3;}
 private void updateTotal(){if(totalLabel==null)return;try{BigDecimal sum=BigDecimal.ZERO;for(String v:values.values())sum=sum.add(number(v));BigDecimal rest=new BigDecimal("100").subtract(sum);String label=t("Entered: ","Σύνολο: ")+sum.stripTrailingZeros().toPlainString()+(percent?" / 100%":t(" valid votes"," έγκυρες ψήφοι"));if(remainderMode()&&rest.signum()>=0)label+="\n"+t("Rest parties (<3% each): ","Λοιπά κόμματα (<3% έκαστο): ")+rest.stripTrailingZeros().toPlainString()+"%";totalLabel.setText(label);totalLabel.setTextColor(percent&&rest.signum()<0?0xFFB4233A:TEAL);}catch(Exception e){totalLabel.setText(t("Check numeric inputs","Ελέγξτε τους αριθμούς"));}}
 private void chooseParty(){List<JSONObject> available=new ArrayList<>();for(JSONObject p:parties)if(!selectedParties.contains(p.optString("id")))available.add(p);LinearLayout content=column();content.setPadding(dp(16),dp(4),dp(16),0);ListView list=new ListView(this);content.addView(list,new LinearLayout.LayoutParams(-1,dp(420)));ArrayAdapter<JSONObject> adapter=new ArrayAdapter<JSONObject>(this,android.R.layout.simple_list_item_1,available){@Override public View getView(int position,View convert,android.view.ViewGroup parent){LinearLayout line=row();line.setPadding(dp(8),dp(4),dp(8),dp(4));View dot=new View(MainActivity.this);dot.setBackground(bg(Color.parseColor(getItem(position).optString("color","#64748B")),5));line.addView(dot,new LinearLayout.LayoutParams(dp(8),dp(38)));TextView label=text(name(getItem(position)),15,INK,true);label.setGravity(Gravity.CENTER_VERTICAL);label.setPadding(dp(12),0,0,0);line.addView(label,new LinearLayout.LayoutParams(-1,dp(52)));return line;}};list.setAdapter(adapter);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(t("Choose party ▾","Επιλογή κόμματος ▾")).setView(content).setNegativeButton(t("Close","Κλείσιμο"),null).create();dialog.getWindow().setWindowAnimations(0);dialog.setOnShowListener(x->dialog.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND));list.setOnItemClickListener((parent,view,position,id)->{int y=scroll==null?0:scroll.getScrollY();selectedParties.add(available.get(position).optString("id"));expanded=true;pendingScrollY=y;dialog.setOnDismissListener(d->render());dialog.dismiss();});dialog.show();}
 private void switchType(int index){if(index==type)return;type=index;editorStep=1;activePoll=null;government.clear();selectedParties.clear();if(index==3){parties.clear();values.clear();winner="";transfers.clear();tieOrder.clear();resultScreen=false;render();return;}future=index==2;loadDataset(index==0?"june":index==1?"eu":"municipality-9186");if(index==2&&!dataset.optString("kind").equals("municipality")){loadDataset(repository.ofType(2).get(0).optString("id"));}render();}
