 private void changeUnits(boolean target){if(percent==target)return;boolean nonzero=values.values().stream().anyMatch(s->!s.equals("0"));if(nonzero){new AlertDialog.Builder(this).setTitle(t("Change input format?","Αλλαγή μορφής εισαγωγής;")).setMessage(t("This clears the current values. Percentages cannot recover exact vote counts. Saved scenarios are retained.","Οι τρέχουσες τιμές θα μηδενιστούν. Τα ποσοστά δεν δίνουν ακριβείς ψήφους. Τα αποθηκευμένα σενάρια διατηρούνται.")).setPositiveButton(t("Clear & switch","Μηδενισμός & αλλαγή"),(d,w)->{percent=target;for(String id:values.keySet())values.put(id,"0");selectedParties.clear();if(activePoll!=null)pollEdited=true;winner="";transfers.clear();tieOrder.clear();render();}).setNegativeButton(t("Cancel","Ακύρωση"),null).show();}else{percent=target;render();}}
 private void customFields(LinearLayout box){String[] labels={t("Total seats","Συνολικές έδρες"),t("Entry threshold (%)","Εκλογικό όριο (%)"),t("Bonus starts at (%)","Έναρξη μπόνους (%)"),t("Base bonus at start","Αρχικό μπόνους"),t("Percentage points per step","Ποσοστιαίες μονάδες ανά βήμα"),t("Seats gained per step","Έδρες ανά βήμα"),t("Maximum bonus","Μέγιστο μπόνους")};for(int i=0;i<custom.length;i++){box.addView(text(labels[i],12,MUTED,true));space(box,5);final int index=i;EditText e=field(custom[i],labels[i],"custom-"+i);watch(e,s->custom[index]=s);box.addView(e);space(box,10);}description(box,t("Example: start 20%, base 0, step 5, seats per step 1. At 35%, bonus = 3. Set base, seats per step and cap to 0 for simple proportional representation.","Παράδειγμα: έναρξη 20%, αρχικό 0, βήμα 5, έδρες ανά βήμα 1. Στο 35% το μπόνους είναι 3. Ορίστε αρχικό, έδρες ανά βήμα και μέγιστο 0 για απλή αναλογική."));}
 private void editParty(JSONObject original){LinearLayout l=column();l.setPadding(dp(24),dp(8),dp(24),0);EditText en=new EditText(this),el=new EditText(this);en.setHint(t("English name","Αγγλικό όνομα"));el.setHint(t("Greek name","Ελληνικό όνομα"));en.setSingleLine();el.setSingleLine();en.setText(original==null?"":original.optString("en"));el.setText(original==null?"":original.optString("el"));l.addView(en);l.addView(el);l.addView(text(t("Coalition member parties (1 = standalone)","Κόμματα συνασπισμού (1 = αυτοτελές)"),13,MUTED,false));EditText members=field(original==null?"1":""+original.optInt("members",1),"1","members");l.addView(members);if(original!=null)description(l,original.optString(greek?"fullEl":"fullEn"));
  AlertDialog d=new AlertDialog.Builder(this).setTitle(t("Party / electoral list","Κόμμα / συνδυασμός")).setView(l).setPositiveButton(t("Save","Αποθήκευση"),null).setNegativeButton(t("Cancel","Ακύρωση"),null).setNeutralButton(original==null?"":t("Remove","Αφαίρεση"),original==null?null:(x,w)->{parties.remove(original);values.remove(original.optString("id"));tieOrder.clear();render();}).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{String a=en.getText().toString().trim(),b=el.getText().toString().trim();if(a.isEmpty()&&b.isEmpty())throw new Exception();if(a.isEmpty())a=b;if(b.isEmpty())b=a;for(JSONObject p:parties)if(p!=original&&(p.optString("en").equalsIgnoreCase(a)||p.optString("el").equalsIgnoreCase(b)))throw new Exception();int count=Integer.parseInt(members.getText().toString());if(count<1||count>100)throw new Exception();JSONObject p=original==null?new JSONObject():original;p.put("en",a).put("el",b).put("members",count);if(original==null){String id="custom-"+UUID.randomUUID();p.put("id",id).put("color",new String[]{"#2979D0","#08A88A","#E56B6F","#9163C7","#D5A631"}[parties.size()%5]);parties.add(p);values.put(id,"0");selectedParties.add(id);}expanded=true;tieOrder.clear();d.dismiss();render();}catch(Exception bad){en.setError(t("Use a unique name and valid member count","Μοναδικό όνομα και έγκυρος αριθμός κομμάτων"));}}));d.show();}
