  for(int i=0;i<parties.size();i++){if(result.seats[i]==0)continue;final int index=i;LinearLayout r=row();TextView label=text(name(parties.get(i)),15,INK,true);r.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView number=text(""+result.seats[i],24,INK,true);number.setTag("seats-"+parties.get(i).optString("id"));r.addView(number);summary.addView(r);description(summary,result.percentages[i].setScale(2,RoundingMode.HALF_UP).toPlainString()+"%  ·  "+(result.seats[i]>=seats()/2+1?t("Majority","Πλειοψηφία"):t("Seats: ","Έδρες: ")+result.seats[i]));LinearLayout track=row();track.setBackground(bg(BG,3));View bar=new View(this);bar.setBackground(bg(colors[index],3));track.addView(bar,new LinearLayout.LayoutParams(0,dp(5),result.seats[i]));track.addView(new View(this),new LinearLayout.LayoutParams(0,dp(5),Math.max(0,seats()-result.seats[i])));summary.addView(track);space(summary,15);}
  long zero=Arrays.stream(result.seats).filter(x->x==0).count();if(zero>0)description(summary,zero+t(" lists received no seats. See their thresholds and quotas below."," συνδυασμοί χωρίς έδρα. Δείτε όρια και υπόλοιπα παρακάτω."));
  if(type==0)renderGovernment();if(activePoll!=null){LinearLayout source=card(body,t("Poll source & assumptions","Πηγή δημοσκόπησης & παραδοχές"));pollNote(source);}
  LinearLayout audit=card(body,t("How the seats were allocated","Πώς κατανεμήθηκαν οι έδρες"));audit.getChildAt(0).setTag("explanation");description(audit,t("Every threshold, quota, remainder and bonus is recorded in order.","Κάθε όριο, μέτρο, υπόλοιπο και μπόνους καταγράφεται με τη σειρά."));int k=0;for(ElectionEngine.Step s:result.steps){String p=s.party<0?"":name(parties.get(s.party));TextView v=text((++k)+".  "+Explanation.format(s,greek,p),14,INK,false);v.setTextIsSelectable(true);audit.addView(v);space(audit,12);}
  body.addView(button(t("Sources & methodology","Πηγές & μεθοδολογία"),"sources",this::sources,false));space(body,10);body.addView(button(t("Share calculation","Κοινοποίηση υπολογισμού"),"share",()->{StringBuilder s=new StringBuilder(title()+"\n"+ruleName()+"\n");for(int i=0;i<parties.size();i++)s.append(name(parties.get(i))).append(": ").append(result.seats[i]).append("\n");for(ElectionEngine.Step step:result.steps)s.append(Explanation.format(step,greek,step.party<0?"":name(parties.get(step.party)))).append("\n");if(type!=3)s.append(dataset.optString("source"));Intent send=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,s.toString());startActivity(Intent.createChooser(send,t("Share calculation","Κοινοποίηση υπολογισμού")));},false));
